import {TIERS,equipmentName,unlockReason,equipmentBonuses} from './equipment-catalog.mjs';
// Turn-based rules. One accepted action advances exactly one actor's turn.
export const SAVE='arena-heir-duels-v1',META='arena-heir-unlocks',ARENA_MAX=30;
export const CLASSES={dwarf:{name:'Borin',title:'Dwarf',trait:'Iron bones · +3 armor',base:[5,2,3,4,1]},ranger:{name:'Rowan',title:'Ranger',trait:'Long stride · +1 movement',base:[2,5,4,2,1]},mage:{name:'Aster',title:'Mage',trait:'Arcane mind · +4 spell damage',base:[1,3,3,2,6]},thorn:{name:'Thornkeeper',title:'Forest Master',trait:'Living bark · recover 2 health when guarding',base:[4,3,3,4,3]}};
export const ATTRS=['strength','speed','defense','vitality','magic'];
export const SPELLS={lightning:{name:'Lightning',cost:20,price:65,tier:1,desc:'A bolt of lightning. Reliable damage at any distance.',cooldown:1},sleep:{name:'Sleep',cost:28,price:90,tier:1,desc:'Skip the enemy’s next turn. Damage wakes them.',cooldown:3},frost:{name:'Frost',cost:18,price:80,tier:1,desc:'Deal damage and halve movement for 2 turns.',cooldown:2},shield:{name:'Aegis',cost:16,price:75,tier:1,desc:'Absorb up to 18 damage from the next hit.',cooldown:2},meteor:{name:'Meteor',cost:32,price:200,tier:2,desc:'A heavy blast. Unlocked by the first crown.',cooldown:2}};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export function newRun(hero,meta={}){if(!Object.hasOwn(CLASSES,hero)||hero==='thorn'&&!meta.thorn)throw Error('Locked fighter');return {v:1,hero,level:1,gold:0,points:0,attrs:Object.fromEntries(ATTRS.map((a,i)=>[a,CLASSES[hero].base[i]])),gear:{melee:0,ranged:hero==='ranger'?1:0,defense:0,boots:0},spells:hero==='mage'?['lightning']:[],goal:null,crown:false,dead:false,tournament:null,offer:null,battle:null,serial:0,result:null,beaten:{}};}
export function stats(r){const a=r.attrs,g=r.gear;const result={hp:55+a.vitality*9,energy:85+a.speed*4,melee:7+a.strength*2+g.melee*7,ranged:g.ranged?8+a.speed*2+g.ranged*5:0,armor:a.defense+g.defense*3+(r.hero==='dwarf'?3:0),magic:8+a.magic*3+(r.hero==='mage'?4:0),stride:Math.max(1,Math.floor(a.speed/3)+1+[0,1,2,3,3,4,4,5][g.boots]+(r.hero==='ranger'?1:0))};const bonuses=equipmentBonuses(g);for(const [key,value]of Object.entries(bonuses))result[key]+=value;return result;}
export const gearName=equipmentName;
const ADVANCED_ATTRIBUTE=[0,0,0,0,8,10,12,14];
function equipmentAttribute(r,slot){if(slot==='defense')return 'defense';if(slot==='boots')return 'speed';if(r.hero==='mage')return 'magic';return r.hero==='ranger'?'speed':'strength';}
export function shop(r,category){if(category==='magic')return Object.entries(SPELLS).map(([id,s])=>({id,...s,owned:r.spells.includes(id),locked:s.tier>(r.crown?2:1),requirement:s.tier>(r.crown?2:1)?'First Crown':'',requiredLevel:1,requiresCrown:s.tier>1,requiredAttribute:null,requiredAttributeValue:0}));const slots=category==='weapons'?['melee','ranged']:['defense','boots'];return slots.flatMap(slot=>TIERS.slice(1).map((t,i)=>{const tier=i+1,attribute=equipmentAttribute(r,slot),attributeValue=ADVANCED_ATTRIBUTE[tier],needs=[unlockReason(r,tier)];if(attributeValue&&r.attrs[attribute]<attributeValue)needs.push(`${attribute[0].toUpperCase()+attribute.slice(1)} ${attributeValue}`);const requirement=needs.filter(Boolean).join(' + '),surcharge=slot==='ranged'?15:0,value=t.price+surcharge,current=r.gear[slot]?TIERS[r.gear[slot]].price+surcharge:0;return {id:slot+':'+tier,slot,tier,name:gearName(r.hero,slot,tier),price:Math.max(0,value-current),value,owned:r.gear[slot]>=tier,locked:!!requirement,requirement,requiredLevel:t.level,requiresCrown:t.crown,requiredAttribute:attributeValue?attribute:null,requiredAttributeValue:attributeValue,trait:t.trait||'',desc:(slot==='boots'?'Move and jump farther.':slot==='defense'?'Reduce incoming damage.':slot==='ranged'?'Attack from a distance.':'Increase close-range damage.')+(t.trait?' '+t.trait+'.':'')};}));}

const SHOP_CATEGORIES=['weapons','armor','magic'];
function goalItem(r,goal){if(!goal||!SHOP_CATEGORIES.includes(goal.category)||typeof goal.id!=='string')return null;const item=shop(r,goal.category).find(i=>i.id===goal.id);return item?{...item,category:goal.category}:null;}
export function suggestGoal(r){const offers=SHOP_CATEGORIES.flatMap(category=>shop(r,category).map(item=>({...item,category}))).filter(i=>!i.owned);offers.sort((a,b)=>Number(a.locked)-Number(b.locked)||a.price-b.price||SHOP_CATEGORIES.indexOf(a.category)-SHOP_CATEGORIES.indexOf(b.category));const item=offers[0];return item?{category:item.category,id:item.id}:null;}
export function setGoal(r,category,id){const item=goalItem(r,{category,id});if(!item||item.owned)return false;r.goal={category,id};return true;}
export function goalStatus(r,goal=r.goal){const item=goalItem(r,goal);if(!item)return null;const goldGap=Math.max(0,item.price-r.gold),levelGap=Math.max(0,(item.requiredLevel||1)-r.level),crownGap=!!item.requiresCrown&&!r.crown,attributeGap=item.requiredAttribute?Math.max(0,item.requiredAttributeValue-r.attrs[item.requiredAttribute]):0;return {...item,goldGap,levelGap,crownGap,attributeGap,ready:!item.owned&&!goldGap&&!levelGap&&!crownGap&&!attributeGap};}

export function buy(r,category,id){if(r.dead||r.battle||r.tournament)return false;const i=shop(r,category).find(i=>i.id===id);if(!i||i.owned||i.locked||r.gold<i.price)return false;r.gold-=i.price;if(category==='magic')r.spells.push(id);else r.gear[i.slot]=i.tier;if(r.goal?.category===category&&(r.goal.id===id||i.slot&&r.goal.id.startsWith(i.slot+':')&&Number(r.goal.id.split(':')[1])<=i.tier))r.goal=null;return true;}
export function allocate(r,key){if(!ATTRS.includes(key)||r.points<1||r.battle||r.dead)return false;r.attrs[key]++;r.points--;return true;}
// A named gallery of rivals. Each card keeps the same fighter, manner and fighting style every time it returns.
export const RIVALS=[
{name:'Flint Ashhand',epithet:'the Stubborn',hero:'dwarf',style:'brute',taunt:'That twig of yours — is it an axe, or kindling?'},
{name:'Lark Quickwater',epithet:'Three-Arrow',hero:'ranger',style:'archer',taunt:'I counted your steps before you took them.'},
{name:'Vesper Dun',epithet:'the Candle',hero:'mage',style:'caster',taunt:'Stand still. This is so much easier when you stand still.'},
{name:'Brann Oxgirth',epithet:'the Wall',hero:'dwarf',style:'bulwark',taunt:'Swing all day. I brought a shield and a lunch.'},
{name:'Sable Wren',epithet:'the Whisper',hero:'ranger',style:'duelist',taunt:'You fight loudly. Loud fighters lose quietly.'},
{name:'Orin Halfmoon',epithet:'the Showman',hero:'ranger',style:'showman',taunt:'They did not pay to watch you. Wave at them, at least!'},
{name:'Maud Cinderhair',epithet:'the Kiln',hero:'mage',style:'caster',taunt:'I have burned finer armor than that for warmth.'},
{name:'Gertok Stonejaw',epithet:'the Avalanche',hero:'dwarf',style:'brute',taunt:'I do not dodge. I have never needed to.'},
{name:'Pell the Lesser',epithet:'the Overconfident',hero:'ranger',style:'showman',taunt:'My brother is the famous one. He is also the slower one.'},
{name:'Isolde Fray',epithet:'the Patient',hero:'mage',style:'bulwark',taunt:'Tire yourself out. I am in no hurry at all.'},
{name:'Harrow Vane',epithet:'the Unblinking',hero:'mage',style:'caster',taunt:'Your next purchase is written on your face. I may buy it first.'},
{name:'Dessa Ironknot',epithet:'the Closer',hero:'dwarf',style:'duelist',taunt:'Three blows. I have watched you fight; three is all it takes.'}];
export function rivalCard(serial){return RIVALS[(Math.max(1,serial)-1)%RIVALS.length];}
// Builds the rival for a given serial without consuming it, so the town and shops can name who waits next.
export function nextRival(r,serial=r.serial+1){const n=Math.max(1,serial),card=rivalCard(n),o=newRun(card.hero);o.level=Math.max(1,r.level-(n%3===1?1:0));for(let i=1;i<o.level;i++){o.attrs.strength++;o.attrs.vitality++;if(i%2)o.attrs.defense++;else o.attrs.speed++;}const showcase=o.level>=15?7:o.level>=13?6:o.level>=11?5:o.level>=9?4:o.level>=7?3:o.level>=6?2:Math.floor(o.level/4);o.gear.melee=Math.min(r.crown?showcase:Math.floor(o.level/4),7);o.gear.defense=Math.min(r.crown?Math.max(0,showcase-1):Math.floor(o.level/5),7);o.name=card.name;o.epithet=card.epithet;o.style=card.style;o.taunt=card.taunt;o.reward=35+o.level*12;o.loss=20+o.level*5;o.id='duel-'+n;o.beatenBefore=Number.isInteger(r.beaten?.[card.name])?r.beaten[card.name]:0;return o;}
export function offer(r){if(r.dead||r.battle||r.tournament)return null;const o=nextRival(r,++r.serial);r.offer=o;return o;}
// How many clean hits from the best available attack drop a rival, so a shop can answer "does this win my next fight?".
export function hitsToDefeat(r,o){const a=stats(r),d=stats(o);let best=Math.max(1,Math.round(a.melee-d.armor*.55));if(a.ranged)best=Math.max(best,Math.max(1,a.ranged-Math.round(d.armor*.5)));for(const id of r.spells)if(['lightning','frost','meteor'].includes(id))best=Math.max(best,Math.max(1,Math.round(a.magic*(id==='meteor'?1.7:id==='frost'?.55:1)-d.armor*.25)));return Math.max(1,Math.ceil((r.tournament?d.hp+Math.round(boutArmor(d)*.5):boutArmor(d)+1)/best));}
export function enterTournament(r){if(r.level<3||r.dead||r.crown||r.battle||r.tournament||r.points)return false;r.tournament={round:0};r.offer=null;r.result=null;return true;}
export function tournamentOffer(r){if(!r.tournament)return null;const round=r.tournament.round,o=newRun(round===2?'thorn':round===0?'ranger':'dwarf',{thorn:true});o.level=round+3;o.name=['Ash the Swift','Granite Guard','Thornkeeper'][round];o.epithet=['First Blade of the Crown','the Unmoved','Forest Master'][round];o.style=['archer','bulwark','caster'][round];o.taunt=['You are late. I have already won twice today.','Come closer. The crowd cannot see you hiding.','The forest remembers every champion. It has forgotten most of them.'][round];o.attrs.strength+=round+1;o.attrs.vitality+=round+1;o.gear.melee=1;o.gear.defense=round?1:0;if(round===2)o.spells=['frost','shield'];o.id='crown-'+round;o.reward=round===2?300:55+round*20;o.loss=0;o.master=round===2;return o;}
function fighter(r,x){return {hero:r.hero,gear:{...r.gear},stats:stats(r),spells:[...r.spells],hp:stats(r).hp,energy:stats(r).energy,x,guard:false,shield:0,sleep:0,frost:0,rattled:0,exposed:0,cd:{}};}
// The crowd arrives bored. Spectacle wakes it up; cautious play sends it back to sleep.
export const CROWD_START=10,CROWD_PAYS=25;
const cheer=(b,amount)=>{b.crowd=clamp(Math.round((Number.isFinite(b.crowd)?b.crowd:CROWD_START)+amount),0,100);};
export function crowdBonus(reward,crowd){return Math.round(Math.max(0,(Number.isFinite(crowd)?crowd:CROWD_START)-CROWD_PAYS)/(100-CROWD_PAYS)*reward*.5);}
export function startFight(r,seed){if(r.dead||r.battle||r.points)return false;const o=r.tournament?tournamentOffer(r):r.offer;if(!o)return false;r.battle={p:fighter(r,5),e:fighter(o,25),opponent:o,turn:'p',count:1,log:'Your turn',previousLog:'The gates open.',outcome:null,events:[],seed:Number.isInteger(seed)?seed>>>0:(r.serial+1)*7919+(r.tournament?.round||0),settled:false,crowd:CROWD_START};r.battle.rule=r.tournament?'tournament':'first-blood';for(const k of ['p','e']){const a=r.battle[k];a.protectionMax=Math.round(boutArmor(a.stats)*(r.tournament?.5:1));a.protection=a.protectionMax;}if(!r.tournament){r.battle.p.x=9;r.battle.e.x=21;}r.result=null;return true;}
export function actions(b,who=b.turn){const a=b[who],e=b[who==='p'?'e':'p'],d=Math.abs(a.x-e.x),near=d<=2,rattle=a.rattled?12:0,opening=e.exposed?12:0,aim=opening-rattle;const defs=[{id:'walk',name:'Advance',cost:3,group:'move',desc:`Move ${a.stats.stride} spaces toward your rival.`},{id:'jump',name:'Jump',cost:8,group:'move',desc:`Leap ${a.stats.stride+4} spaces toward your rival. Better boots make this leap spectacular.`},{id:'charge',name:'Charge',cost:14,far:true,group:'attack',damage:Math.max(1,Math.round(a.stats.melee*1.15-e.stats.armor*.45)),chance:clamp(76+aim+(a.stats.stride-e.stats.stride)*2,48,96),desc:'Rush across the sand. If you reach melee range, strike and drive the rival back.'},{id:'retreat',name:'Retreat',cost:3,group:'move',desc:'Step away. Gain distance and make ranged attacks safer.'},{id:'guard',name:'Guard',cost:0,group:'guard',desc:'Reduce the next hit and recover 8 energy.'},{id:'rest',name:'Rest',cost:0,group:'guard',desc:'Recover 24 energy, but become exposed to the rival’s next attack.'},{id:'taunt',name:'Taunt',cost:0,far:true,group:'crowd',desc:'Play to the crowd and rattle your rival’s aim, but leave yourself open. Needs room.'},{id:'shove',name:'Shove',cost:7,near:true,group:'guard',damage:Math.max(1,Math.round(a.stats.melee*.4-e.stats.armor*.2)),chance:clamp(82+aim+(a.stats.stride-e.stats.stride)*2,50,97),desc:'A close shove that breaks guard and knocks the rival back.'}];for(const [id,name,cost,mul,ch]of [['quick','Quick',5,.7,92],['normal','Strike',9,1,80],['heavy','Heavy',16,1.5,62]])defs.push({id,name,cost,near:true,group:'attack',damage:Math.max(1,Math.round(a.stats.melee*mul-e.stats.armor*.55)),chance:clamp(ch+aim+(a.stats.stride-e.stats.stride)*2,45,97),desc:id==='quick'?'Fast and accurate. A clean finisher.':id==='heavy'?'Crush guard and knock the rival backward. Powerful, but risky.':'A balanced close-range blow.'});if(a.stats.ranged)defs.push({id:'shoot',name:'Shoot',cost:9,group:'attack',damage:Math.max(1,a.stats.ranged-Math.round(e.stats.armor*.5)),chance:clamp((near?62:88)+opening-rattle,40,97),desc:near?'Harder to aim this close.':'Attack without closing the distance.'});for(const id of a.spells){const s=SPELLS[id];defs.push({id,name:s.name,cost:s.cost,group:'magic',damage:['lightning','frost','meteor'].includes(id)?Math.max(1,Math.round(a.stats.magic*(id==='meteor'?1.7:id==='frost'?.55:1)-e.stats.armor*.25)):undefined,chance:clamp((id==='sleep'?90:100)+opening-rattle,40,100),desc:s.desc,spell:true});}return defs.map(d=>({...d,disabled:!!b.outcome||a.energy<d.cost||d.near&&!near||d.far&&near||(a.cd[d.id]||0)>0||(d.id==='retreat'&&(a.x===0||a.x===ARENA_MAX)),reason:d.near&&!near?'Too far':d.far&&near?'Too close':a.cd[d.id]>0?`${a.cd[d.id]} turn cooldown`:a.energy<d.cost?'Low energy':''}));}
function random(b){b.seed=(Math.imul(b.seed,1664525)+1013904223)>>>0;return b.seed/4294967296;}
export function act(b,id,who=b.turn){if(b.outcome||b.turn!==who)return false;const a=b[who],other=who==='p'?'e':'p',e=b[other],move=actions(b,who).find(v=>v.id===id);if(!move||move.disabled)return false;const from=a.x;b.events=[];a.energy-=move.cost;a.guard=false;for(const k in a.cd)a.cd[k]=Math.max(0,a.cd[k]-1);const dir=Math.sign(e.x-a.x)||1,step=Math.max(1,Math.floor(a.stats.stride/(a.frost?2:1)));if(a.frost)a.frost--;a.rattled=0;const mine=who==='p',wasGuarded=!!e.guard;
let text=`${who==='p'?'You':b.opponent.name}: ${move.name}`;
if(id==='walk'||id==='jump'){const distance=step+(id==='jump'?4:0);a.x=clamp(a.x+dir*Math.min(distance,Math.max(0,Math.abs(e.x-a.x)-1)),0,ARENA_MAX);}
else if(id==='retreat'){a.x=clamp(a.x-dir*step,0,ARENA_MAX);cheer(b,mine?-3:0);}
else if(id==='guard'){a.guard=true;a.energy=Math.min(a.stats.energy,a.energy+8);a.cd[id]=2;if(a.hero==='thorn')a.hp=Math.min(a.stats.hp,a.hp+2);}
else if(id==='rest'){a.energy=Math.min(a.stats.energy,a.energy+24);a.exposed=1;cheer(b,mine?-4:0);text+=' · Exposed';}
else if(id==='taunt'){a.energy=Math.min(a.stats.energy,a.energy+4);a.exposed=1;e.rattled=1;a.cd[id]=3;cheer(b,mine?14:4);text+=mine?' · The crowd answers you · Exposed':' · '+b.opponent.name+' plays to the crowd';b.events.push({type:'taunt',who});}
else if(id==='shield'){a.shield=18;a.cd[id]=SPELLS[id].cooldown;}
else {if(id==='charge')a.x=clamp(a.x+dir*Math.min(step+7,Math.max(0,Math.abs(e.x-a.x)-1)),0,ARENA_MAX);const closeEnough=Math.abs(a.x-e.x)<=2;if(id==='charge'&&!closeEnough){text+=' · Closing fast';cheer(b,mine?2:0);}else{e.exposed=0;const hit=random(b)*100<(move.chance||100);if(move.spell)a.cd[id]=SPELLS[id].cooldown;if(!hit){if(id==='heavy')a.exposed=1;text+=id==='heavy'?' · Miss! · Exposed':' · Miss!';b.events.push({type:'miss',target:other});cheer(b,mine?-2:0);}else if(id==='sleep'){e.sleep=1;text+=' · Asleep';cheer(b,mine?5:1);}else{const crit=random(b)*100<clamp(9+Math.max(0,a.stats.stride-e.stats.stride)*3,4,30),guardScale=e.guard?(id==='heavy'?.8:id==='charge'?.65:id==='shove'?.55:.35):1;let damage=Math.max(1,Math.round(move.damage*(crit?1.6:1)*guardScale)),absorbed=0;if(e.shield){absorbed=Math.min(e.shield,damage);damage-=absorbed;e.shield=0;}const before=e.protection||0,armorDamage=Math.min(before,damage);e.protection=Math.max(0,before-armorDamage);damage-=armorDamage;if(before>0&&!e.protection)b.events.push({type:'armor-break',target:other});e.hp=Math.max(0,e.hp-damage);e.sleep=0;e.guard=false;if(id==='frost')e.frost=2;const knockback=id==='heavy'?2:id==='shove'?3:id==='charge'?1:0;if(knockback)e.x=clamp(e.x+dir*knockback,0,ARENA_MAX);text+=crit?` · CRITICAL! ${damage+armorDamage}`:` · ${damage+armorDamage} damage`;if(armorDamage)text+=' · Armor hit';if(b.rule==='first-blood'&&damage>0)text+=' · FIRST BLOOD!';if(wasGuarded&&(id==='heavy'||id==='charge'||id==='shove'))text+=' · Guard broken';b.events.push({type:'hit',target:other,damage,armorDamage,crit,blocked:wasGuarded,absorbed,knockback});cheer(b,mine?(crit?9:id==='heavy'||id==='charge'?6:move.spell?5:2):1);}}}
b.events.unshift({type:'action',who,id,from,to:a.x});b.previousLog=b.log;b.log=text;if(e.hp<=0||(b.rule==='first-blood'&&e.hp<e.stats.hp))b.outcome=who==='p'?'win':'loss';else {b.turn=other;b.count++;if(e.sleep){e.sleep=0;for(const k in e.cd)e.cd[k]=Math.max(0,e.cd[k]-1);b.log+=' · '+(other==='e'?b.opponent.name:'You')+' missed a turn';b.turn=who;b.count++;}}return true;}
// One ladder per fighting style, so a named rival keeps its manner from fight to fight.
export function ai(b){const all=actions(b,'e').filter(a=>!a.disabled),has=id=>all.some(v=>v.id===id),a=b.e,e=b.p,near=Math.abs(a.x-e.x)<=2,style=b.opponent?.style||'duelist';
 if(a.energy<20)return 'rest';
 if((b.rule==='first-blood'?(a.protection||0)<a.protectionMax*.35:a.hp<a.stats.hp*.35)&&!a.shield&&has('shield'))return 'shield';
 if(style==='brute'){if(near)return has('heavy')&&a.energy>=30?'heavy':(b.rule==='first-blood'?(e.protection||0)<15:e.hp<15)?'quick':'normal';if(has('charge')&&a.energy>35)return 'charge';return has('jump')?'jump':'walk';}
 if(style==='bulwark'){if((b.rule==='first-blood'?(a.protection||0)<a.protectionMax*.55:a.hp<a.stats.hp*.55)&&!a.guard&&has('guard'))return 'guard';if(has('frost')&&!e.frost)return 'frost';if(near)return has('heavy')&&a.energy>=34?'heavy':'normal';if(has('shoot'))return 'shoot';return has('walk')?'walk':'rest';}
 if(style==='archer'){if(near&&has('retreat'))return 'retreat';if(has('shoot'))return 'shoot';if(has('frost')&&!e.frost)return 'frost';if(near)return 'normal';return 'walk';}
 if(style==='caster'){if(has('frost')&&!e.frost)return 'frost';if(has('meteor')&&a.energy>45)return 'meteor';if(has('lightning')&&a.energy>30)return 'lightning';if(near&&has('retreat'))return 'retreat';if(has('shoot'))return 'shoot';return near?'normal':'walk';}
 if(style==='showman'){if(has('taunt'))return 'taunt';if(has('lightning')&&a.energy>35)return 'lightning';if(near)return e.guard&&has('shove')?'shove':(b.rule==='first-blood'?(e.protection||0)<15:e.hp<15)?'quick':has('heavy')&&a.energy>=40?'heavy':'normal';if(has('shoot'))return 'shoot';return 'walk';}
 if(has('lightning')&&a.energy>35)return 'lightning';if(has('frost')&&!e.frost)return 'frost';if(near)return (b.rule==='first-blood'?(e.protection||0)<15:e.hp<15)?'quick':'normal';if(has('shoot'))return 'shoot';return a.energy>35?'jump':'walk';}
export function settle(r,meta){const b=r.battle;if(b?.opponent?.trial&&b.outcome&&!b.settled){b.settled=true;const won=b.outcome==='win';r.battle=null;if(won)return finishTrial(r);r.intro='pending';r.result={won:false,gold:0,trial:true,dead:false,name:'Gatekeeper'};return r.result;}if(!b?.outcome||b.settled)return false;b.settled=true;const won=b.outcome==='win',o=b.opponent,crowd=clamp(Math.round(Number.isFinite(b.crowd)?b.crowd:CROWD_START),0,100);let gold=0,bonus=0;if(won){bonus=crowdBonus(o.reward,crowd);gold=o.reward+bonus;r.gold+=gold;r.level++;r.points+=3;if(!r.beaten||typeof r.beaten!=='object'||Array.isArray(r.beaten))r.beaten={};r.beaten[o.name]=(Number.isInteger(r.beaten[o.name])?r.beaten[o.name]:0)+1;if(r.tournament){r.tournament.round++;if(o.master){r.crown=true;meta.thorn=true;r.tournament=null;}}}else if(r.tournament){r.dead=true;r.tournament=null;}else{gold=-Math.min(r.gold,o.loss);r.gold+=gold;}r.result={won,gold,master:won&&!!o.master,dead:r.dead,name:o.name,epithet:o.epithet||'',crowd,crowdBonus:bonus,reward:won?o.reward:0,beaten:won?r.beaten?.[o.name]||1:0};r.battle=null;r.offer=null;return r.result;}
export function surrender(r,meta){if(!r.battle)return false;r.battle.outcome='loss';return settle(r,meta);}
export function load(raw,meta={}){try{const r=JSON.parse(raw);if(r.v!==1||!Object.hasOwn(CLASSES,r.hero)||r.hero==='thorn'&&!meta.thorn)return null;for(const k of ['level','gold','points','serial'])if(!Number.isSafeInteger(r[k])||r[k]<0||r[k]>1e7)return null;if(r.level<1||typeof r.dead!=='boolean'||typeof r.crown!=='boolean'||!r.attrs||!r.gear||!Array.isArray(r.spells))return null;if(ATTRS.some(k=>!Number.isInteger(r.attrs[k])||r.attrs[k]<1||r.attrs[k]>1e6)||['melee','ranged','defense','boots'].some(k=>!Number.isInteger(r.gear[k])||r.gear[k]<0||r.gear[k]>7)||r.spells.some(s=>!Object.hasOwn(SPELLS,s)))return null;if(r.tournament&&(!Number.isInteger(r.tournament.round)||r.tournament.round<0||r.tournament.round>2||r.crown||r.dead))return null;if(r.battle){const b=r.battle;if(!['p','e'].includes(b.turn)||!Number.isInteger(b.seed)||!b.opponent||!['win','loss',null].includes(b.outcome))return null;for(const k of ['p','e']){const a=b[k];if(!a||!Number.isFinite(a.hp)||a.hp<0||!Number.isFinite(a.energy)||a.energy<0||!Number.isInteger(a.x)||a.x<0||a.x>ARENA_MAX||!a.stats||!a.cd||!Array.isArray(a.spells)||a.spells.some(s=>!Object.hasOwn(SPELLS,s)))return null;for(const n of ['hp','energy','melee','ranged','armor','magic','stride'])if(!Number.isFinite(a.stats[n])||a.stats[n]<0)return null;a.rattled=Number.isInteger(a.rattled)&&a.rattled>0?1:0;a.exposed=Number.isInteger(a.exposed)&&a.exposed>0?1:0;}b.events=[];b.crowd=clamp(Number.isFinite(b.crowd)?Math.round(b.crowd):CROWD_START,0,100);b.previousLog=typeof b.previousLog==='string'?b.previousLog:'The duel continues.';}
if(!r.beaten||typeof r.beaten!=='object'||Array.isArray(r.beaten))r.beaten={};else for(const k of Object.keys(r.beaten))if(!Number.isInteger(r.beaten[k])||r.beaten[k]<1||r.beaten[k]>1e7)delete r.beaten[k];
if(!goalItem(r,r.goal)||goalItem(r,r.goal)?.owned)r.goal=null;if(r.intro!==undefined&&!['pending','trial','done'].includes(r.intro))return null;if(r.battle?.rule){if(!['first-blood','tournament'].includes(r.battle.rule))return null;for(const k of ['p','e']){const a=r.battle[k];if(!Number.isFinite(a.protection)||!Number.isFinite(a.protectionMax)||a.protection<0||a.protection>a.protectionMax)return null;}}return r;}catch{return null;}}

export function boutArmor(stats){return Math.max(12,Math.min(180,Math.round(stats.hp*.7+stats.armor*3)));}
export function prepareTrial(r){if(r.level!==1||r.serial||r.battle||r.intro)return false;r.intro='pending';return true;}
export function startTrial(r,seed){if(r.intro!=='pending'||r.battle)return false;const o=newRun('dwarf');o.name='Gatekeeper';o.style='duelist';o.trial=true;o.reward=0;o.loss=0;o.attrs={strength:1,speed:1,defense:1,vitality:1,magic:1};r.offer=o;if(!startFight(r,seed))return false;r.intro='trial';r.battle.p.x=10;r.battle.e.x=16;r.battle.e.protectionMax=18;r.battle.e.protection=18;r.battle.e.stats.melee=7;r.battle.log='Jump closer, then choose your attack.';return true;}
export function finishTrial(r){if(!['pending','trial'].includes(r.intro)||r.battle)return false;r.intro='done';r.gold+=150;r.points+=3;r.offer=null;r.result={won:true,gold:150,trial:true,dead:false,name:'Gatekeeper'};return r.result;}
